        Case(
            "talk grpconf-india-2026:1287552",
            "Building Low-Latency gRPC Architectures for Cloud Robotics and Industrial AI\u000AIndustrial robotics platforms increasingly depend on gRPC for efficient communication between edge controllers, AI services, and cloud-native microservices. This session presents a multi-tier cloud architecture that combines operations sites, Local Zones, provider backbones, and cloud regions to deliver deterministic latency and resilient service communication. It discusses workload placement, scalable gRPC service design, BFD-assisted failure recovery, traffic engineering, and graceful degradation that enables robotic systems to continue operating during network disruptions. Attendees will gain practical guidance for designing reliable, low-latency gRPC-based architectures that support large robotic fleets and industrial AI applications while maintaining operational continuity and predictable performance.",
            "101,2311,2659,1011,2397,9407,24665,15042,4294,2015,2005,6112,21331,1998,3919,9932,3919,21331,7248,6233,12530,2006,24665,15042,2005,8114,4807,2090,3341,21257,1010,9932,2578,1010,1998,6112,1011,3128,12702,8043,7903,2229,1012,2023,5219,7534,1037,4800,1011,7563,6112,4294,2008,13585,3136,4573,1010,2334,10019,1010,10802,21505,2015,1010,1998,6112,4655,2000,8116,28283,25300,10074,2397,9407,1998,24501,18622,4765,2326,4807,1012,2009,15841,2147,11066,11073,1010,26743,3468,24665,15042,2326,2640,1010,28939,2094,1011,7197,4945,7233,1010,4026,3330,1010,1998,19415,16627,2008,12939,20478,3001,2000,3613,4082,2076,2897,20461,2015,1012,19973,2097,5114,6742,8606,2005,12697,10539,1010,2659,1011,2397,9407,24665,15042,1011,2241,4294,2015,2008,2490,2312,20478,25515,1998,3919,9932,5097,2096,8498,6515,13717,1998,21425,2836,1012,102",
            156,
