        Case(
            "talk grpconf-india-2026:1314175",
            "Open Source Projects and AI Security\u000AgRPC team members will discuss how the gRPC team took a proactive stance on the new world of AI vulnerability identification.\u000A\u000ALearn how the gRPC team worked with the author of the newly open-sourced Mantis Skills (a Portable Toolkit for Building Security Review Harnesses) to identify and address vulnerabilities across their codebase, and build up continuous vulnerability scanning across the gRPC languages.",
            "101,2330,3120,3934,1998,9932,3036,24665,15042,2136,2372,2097,6848,2129,1996,24665,15042,2136,2165,1037,4013,19620,11032,2006,1996,2047,2088,1997,9932,18130,8720,1012,4553,2129,1996,24665,15042,2136,2499,2007,1996,3166,1997,1996,4397,2330,1011,23184,2158,7315,4813,1006,1037,12109,6994,23615,2005,2311,3036,3319,17445,2229,1007,2000,6709,1998,4769,24728,19666,6906,14680,2408,2037,3642,15058,1010,1998,3857,2039,7142,18130,13722,2408,1996,24665,15042,4155,1012,102",
            89,
