        Case(
            "talk kubecon-cloudnativecon-north-america-2026:1289630",
            "GitOps Without You Writing YAML: How Flux Grounds AI Agents in Real APIs\u000AAI is evolving fast, and agents are becoming the YAML engineers humans never wanted to be. The Flux project is embracing this shift by building the tools that solve the hard parts: stopping hallucinated fields and invented enum values, cutting the tokens costs and tool calls agents waste reconstructing APIs from stale training data, and giving them the actual meaning of every field instead of a plausible guess.\u000A\u000AThis talk shows how Flux is closing the agentic loop with static validation using the API server's own semantics, a schema catalog covering 100+ cloud native projects, a public MCP server that grounds every generated manifest in the real APIs, and the GitOps Agent Skills that turn assistants into repository auditors.\u000A\u000AThe talk ends with the Flux roadmap and how you can contribute to the project even if you use AI coding agents.",
            "101,21025,25181,2302,2017,3015,8038,19968,1024,2129,19251,5286,9932,6074,1999,2613,17928,2015,9932,2003,20607,3435,1010,1998,6074,2024,3352,1996,8038,19968,6145,4286,2196,2359,2000,2022,1012,1996,19251,2622,2003,23581,2023,5670,2011,2311,1996,5906,2008,9611,1996,2524,3033,1024,7458,2534,14194,15833,4249,1998,8826,4372,2819,5300,1010,6276,1996,19204,2015,5366,1998,6994,4455,6074,5949,28667,5644,26310,17928,2015,2013,26729,2731,2951,1010,1998,3228,2068,1996,5025,3574,1997,2296,2492,2612,1997,1037,24286,3984,1012,2023,2831,3065,2129,19251,2003,5494,1996,4005,2594,7077,2007,10763,27354,2478,1996,17928,8241,1005,1055,2219,28081,1010,1037,8040,28433,12105,5266,2531,1009,6112,3128,3934,1010,1037,2270,11338,2361,8241,2008,5286,2296,7013,19676,1999,1996,2613,17928,2015,1010,1998,1996,21025,25181,4005,4813,2008,2735,16838,2046,22409,20964,2015,1012,1996,2831,4515,2007,1996,19251,2346,2863,2361,1998,2129,2017,2064,9002,2000,1996,2622,2130,2065,2017,2224,9932,16861,6074,1012,102",
