        Case(
            "talk mcp-dev-summit-nairobi-2026:1319724",
            "Bridging Legacy Systems and LLMs: Practical Enterprise MCP Integration Patterns\u000AEnterprise adoption of AI agents often stalls when attempting to interface with existing legacy platforms, ERPs, and strict internal compliance frameworks. This session presents a practical case study on integrating the Model Context Protocol (MCP) into internal platforms and developer workflows to bridge traditional infrastructure with LLM tools. We will explore architectural patterns for wrapping legacy APIs and database services with MCP servers, establishing governance and permissioning layers, and maintaining full audit trails without rewriting core business logic. Attendees will leave with actionable strategies for incremental MCP rollout, managing change across engineering teams, and ensuring enterprise-grade compliance in agentic workflows.",
            "101,7987,3593,4726,8027,3001,1998,2222,5244,1024,6742,6960,11338,2361,8346,7060,6960,9886,1997,9932,6074,2411,19753,2043,7161,2000,8278,2007,4493,8027,7248,1010,9413,4523,1010,1998,9384,4722,12646,7705,2015,1012,2023,5219,7534,1037,6742,2553,2817,2006,22380,1996,2944,6123,8778,1006,11338,2361,1007,2046,4722,7248,1998,9722,2147,12314,2015,2000,2958,3151,6502,2007,2222,2213,5906,1012,2057,2097,8849,6549,7060,2005,12252,8027,17928,2015,1998,7809,2578,2007,11338,2361,14903,1010,7411,10615,1998,6656,2075,9014,1010,1998,8498,2440,15727,9612,2302,2128,18560,4563,2449,7961,1012,19973,2097,2681,2007,2895,3085,9942,2005,4297,28578,21050,11338,2361,4897,5833,1010,6605,2689,2408,3330,2780,1010,1998,12725,6960,1011,3694,12646,1999,4005,2594,2147,12314,2015,1012,102",
